#include <vector>

class Solution {
public:
    int countTriplets(std::vector<int>& arr) {
        int n = arr.size();
        std::vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] ^ arr[i];
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            for (int k = i + 1; k < n; ++k) {
                if (pref[i] == pref[k + 1]) ans += k - i;
            }
        }
        return ans;
    }
};

class Solution {
    public int countTriplets(int[] arr) {
        int n = arr.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] ^ arr[i];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int k = i + 1; k < n; k++) {
                if (pref[i] == pref[k + 1]) ans += k - i;
            }
        }
        return ans;
    }
}

var countTriplets = function(arr) {
    const n = arr.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] ^ arr[i];
    let ans = 0;
    for (let i = 0; i < n; i++) {
        for (let k = i + 1; k < n; k++) {
            if (pref[i] === pref[k + 1]) ans += k - i;
        }
    }
    return ans;
};
